use std::{collections::BTreeSet,path::{Path,PathBuf,Component},io::{self,Write}};
const ROLES:[&str;7]=["sparse_slots","system_accessors","stats","actions","declare_ids","declare","ui_types"];
fn document(name:&str,filename:&str,body:&str)->String{let mut text=format!("// GENERATED by tools/analyze: `analyze gen {}`. Do not edit by hand; edit the declarations it reads.\n// Written to code/engine/_generated/{}; not committed: every build regenerates it (`analyze gen`).\n\n",name,filename);text.push_str(body);if !text.ends_with('\n'){text.push('\n')}text}
fn engine(root:&Path)->Result<dq_analyze::run::Engine,String>{dq_analyze::run::Engine::new(dq_analyze::run::registry(),dq_analyze::run::Options{root:root.to_path_buf(),scopes_from:Some(root.to_path_buf()),lints:vec!["sem/keys".into()],raw:true,no_cache:true,..Default::default()})}
fn safe_write(root:&Path,relative:&str,text:&str)->io::Result<()>{let relative=Path::new(relative);if relative.is_absolute()||relative.components().any(|p|matches!(p,Component::ParentDir|Component::RootDir|Component::Prefix(_))){return Err(io::Error::new(io::ErrorKind::InvalidInput,"oracle generator output escapes private scratch"))}let target=root.join(relative);std::fs::create_dir_all(target.parent().ok_or_else(||io::Error::other("output parent absent"))?)?;let mut file=std::fs::OpenOptions::new().create_new(true).write(true).open(target)?;file.write_all(text.as_bytes())}
fn legacy_file_of(sem:&sem::Sem,location:dreammaker::Location)->Option<&str>{if location.is_builtins(){None}else{let relative=sem.rel(location);(!relative.is_empty()).then_some(relative)}}
fn legacy_canonical_read_key(kind:&sem::reads::ReadKind,name:&str,keys:&BTreeSet<String>,defines:&BTreeSet<String>)->String{if *kind==sem::reads::ReadKind::Accessor&&keys.contains(name){format!("capkey:[{name}]")}else if *kind==sem::reads::ReadKind::Accessor&&defines.contains(name){format!("[{name}]")}else{name.to_owned()}}

fn fixedpoint_registry()->Vec<Box<dyn sem::gen::Generator>>{
 let mut originals:Vec<Box<dyn sem::gen::Generator>>=Vec::new();deps::register(&mut originals);frozen_reads::register(&mut originals);frozen_plans::register(&mut originals);frozen_tracked::register(&mut originals);auto_tracked::register(&mut originals);original_derived_transport::register(&mut originals);
 let mut registry=sem::gen::registry();for slot in &mut registry{if let Some(index)=originals.iter().position(|original|original.name()==slot.name()){*slot=originals.remove(index)}}assert!(originals.is_empty(),"every immutable purpose producer must replace its actual registered slot");assert_eq!(registry.len(),13);assert_eq!(registry.iter().filter(|generator|generator.stage()==0).count(),8);assert_eq!(registry.iter().filter(|generator|generator.stage()==1).count(),5);registry
}
fn fixedpoint_owner(tree:&tree::Tree)->Result<sem::SemHandle,Box<dyn std::error::Error>>{
 let omissions=sem::ObservedGenerationOmissions::probe(&tree.root)?;let real=std::fs::read_to_string(tree.root.join("deepquarry.dme")).is_ok_and(|text|text.contains("#include"));let owner=if omissions.paths().next().is_some()&&real{sem::generation_original_for(tree,omissions)?}else{sem::sem_for(tree).ok_or("ordinary complete old semantic owner unavailable")?};if !owner.errors.is_empty(){return Err(format!("actual old fixedpoint preparation failed: {:?}",owner.errors).into())}Ok(owner)
}
fn fixedpoint(root:&Path,original_case:Option<&str>)->Result<(),Box<dyn std::error::Error>>{
 use sem::gen::{GenResult,State};
 let registry=fixedpoint_registry();let order:Vec<_>=registry.iter().map(|generator|generator.name()).collect();let stages:std::collections::HashMap<_,_>=registry.iter().map(|generator|(generator.name(),generator.stage())).collect();drop(registry);
 let mut saved:Option<Vec<GenResult>>=None;let mut settled=None;let mut settled_pass=0;
 for pass in 0..5{
  let current=engine(root)?;let owner=fixedpoint_owner(&current.tree)?;
  let zero=sem::gen::run_stage_with_original_registry(root,&current.tree,&[],false,Some(0),fixedpoint_registry);if let Some(row)=zero.iter().find(|row|row.state==State::Stale){return Err(format!("actual old stage 0 output write remained stale: {}",row.path.display()).into())}let wrote_zero=zero.iter().filter(|row|row.state==State::Written).count();
  if wrote_zero!=0{eprintln!("OLD_GENERATION_FIXEDPOINT_PASS pass={} stage0_written={} stage1=not-run",pass+1,wrote_zero);saved=None;drop(owner);drop(current);continue}
  if let Some(one)=saved.take(){let mut all=zero;all.extend(one);all.sort_by_key(|row|order.iter().position(|name|*name==row.name).unwrap_or(usize::MAX));settled=Some(all);settled_pass=pass+1;eprintln!("OLD_GENERATION_FIXEDPOINT_PASS pass={} stage0_written=0 stage1=saved",pass+1);break}
  let one=sem::gen::run_stage_with_original_registry(root,&current.tree,&[],false,Some(1),fixedpoint_registry);if let Some(row)=one.iter().find(|row|row.state==State::Stale){return Err(format!("actual old stage 1 output write remained stale: {}",row.path.display()).into())}let wrote_one=one.iter().filter(|row|row.state==State::Written).count();let mut all=zero;all.extend(one);all.sort_by_key(|row|order.iter().position(|name|*name==row.name).unwrap_or(usize::MAX));eprintln!("OLD_GENERATION_FIXEDPOINT_PASS pass={} stage0_written=0 stage1_written={}",pass+1,wrote_one);
  if wrote_one==0{settled=Some(all);settled_pass=pass+1;break}
  let(one,_zero):(Vec<_>,Vec<_>)=all.into_iter().partition(|row|stages.get(row.name).copied().unwrap_or(0)==1);saved=Some(one);drop(owner);drop(current);
 }
 let results=settled.ok_or("actual original generation did not converge within its existing five-pass limit")?;
 // All files come from the actual old writer after convergence; no generated
 // body/answer from native compilation or a prior oracle phase is supplied.
 for name in &order{let mut files=Vec::new();let mut diagnostics=Vec::new();for row in results.iter().filter(|row|row.name==*name){let relative=row.path.strip_prefix(root)?.to_string_lossy().replace('\\',"/");files.push((relative,std::fs::read_to_string(&row.path)?));diagnostics.extend(row.diags.iter().map(|diag|(&diag.rel,diag.line,&diag.msg)));}println!("OLD_GENERATION_FIXEDPOINT_FULL={}",serde_json::json!({"generator":name,"files":files,"diagnostics":diagnostics}));if let Some(case)=original_case{println!("OLD_ORIGINAL_GENERATION_FULL={}",serde_json::json!({"case":case,"generator":name,"files":files,"diagnostics":diagnostics}));}}
 println!("OLD_GENERATION_FIXEDPOINT_SETTLED={}",serde_json::json!({"schema":"original-generation-fixedpoint-v1","settled":true,"passes":settled_pass,"stage_zero":8,"stage_one":5,"generators":order}));Ok(())
}

