 dq_analyze::sem::incremental::disable_capture();let fixture=PathBuf::from(std::env::args().nth(1).ok_or("Auto fixture root required")?);let mode=std::env::args().nth(2);let configured=mode.as_deref()==Some("configured");let original_case=mode.as_deref().and_then(|value|value.strip_prefix("original-")).and_then(|value|value.strip_suffix("-fixedpoint"));if original_case.is_some_and(|case|!original_initial::CASES.contains(&case)){return Err("unknown original-purpose initial case".into())}let fixed=mode.as_deref()==Some("cold-fixedpoint")||original_case.is_some();let cold=mode.as_deref()==Some("cold")||fixed;let fixture=if fixture.is_absolute(){fixture}else{std::env::current_dir()?.join(fixture)};let root=dm_preprocess::regions::canonical_path(&test_scratch::dir("original-generation-auto"));std::fs::create_dir_all(root.join("code/tests"))?;std::fs::create_dir_all(root.join("tools/ci"))?;for relative in ["code/probe.dm","code/tests/only.dm"]{std::fs::copy(fixture.join(relative),root.join(relative))?;}if !cold{std::fs::write(root.join("code/extra.dm"),"// actual uncompiled source, borrowed only by raw policy\n")?;}if configured{std::fs::copy(fixture.join("tools/ci/lint_scopes.toml"),root.join("tools/ci/lint_scopes.toml"))?;}let mut manifest=String::new();let registry=dq_analyze::sem::gen::registry();for name in ["sparse_slots","system_accessors","stats","actions","declare_ids","declare","tracked_lists","deps","auto_tracked","reads","plans"]{let generator=registry.iter().find(|g|g.name()==name).ok_or("actual registered manifest output missing")?;manifest.push_str(&format!("#include \"{}/{}\"\n",dq_analyze::sem::gen::OUT_DIR,generator.output()));}manifest.push_str("#include \"code/_generated/reads.dm\"\n");manifest.push_str(&std::fs::read_to_string(fixture.join("deepquarry.dme"))?);if cold{manifest=std::fs::read_to_string(fixture.join("deepquarry.dme"))?;}if let Some(case)=original_case{if case!="real"{std::fs::create_dir_all(root.join("code/__defines"))?;std::fs::write(root.join("code/__defines/original_generation.dm"),original_initial::synthetic_support(manifest.as_bytes()))?;}let probe=root.join("code/probe.dm");std::fs::write(&probe,original_initial::guarded_probe(&std::fs::read_to_string(&probe)?))?;match original_initial::manifest(case,manifest.into_bytes()){Some(bytes)=>std::fs::write(root.join("deepquarry.dme"),bytes)?,None=>()}}else{std::fs::write(root.join("deepquarry.dme"),manifest)?;}
 let registry=dq_analyze::sem::gen::registry();let initial=engine(&root)?;let mut staged=Vec::new();
 // ALL seven judge the SAME initial tree. Writes start only after their loans
 // end; no native output or answer is supplied to this independent recipe.
 for name in ROLES{let generator=registry.iter().find(|g|g.name()==name).ok_or("original source producer absent")?;let cx=dq_analyze::sem::gen::GenCx::new(&initial.tree,&root);let mut output=dq_analyze::sem::gen::GenOut::default();generator.generate(&cx,&mut output);let files=if generator.output().is_empty(){generator.files(&cx,&mut output)}else{vec![(format!("{}/{}",dq_analyze::sem::gen::OUT_DIR,generator.output()),document(generator.name(),generator.output(),output.text()))]};
  if !output.diags.is_empty(){return Err(format!("original source-seven findings: {:?}",output.diags.iter().map(|d|(&d.rel,d.line,&d.msg)).collect::<Vec<_>>()).into())}let wire=serde_json::json!({"generator":name,"files":&files,"diagnostics":[]});println!("OLD_AUTO_BOOTSTRAP_SOURCE_FILE={wire}");staged.push(files);
 }drop(initial);
 for files in staged{for(relative,text)in files{safe_write(&root,&relative,&text)?;}}
